import json
import urllib.error
import urllib.request


class HTTPStatusError(Exception):
    def __init__(self, status: int, url: str):
        super().__init__(f"HTTP {status} for {url}")
        self.status = status
        self.url = url


def _send(url: str, timeout: float) -> tuple[int, bytes]:
    request = urllib.request.Request(
        url,
        headers={"Accept": "application/json", "User-Agent": "httpkit/1.0"},
        method="GET",
    )
    try:
        with urllib.request.urlopen(request, timeout=timeout) as response:
            return response.status, response.read()
    except urllib.error.HTTPError as exc:
        exc.close()
        return exc.code, b""


def fetch_json(url: str, timeout: float = 5.0, retries: int = 0) -> object:
    attempts = retries + 1
    for attempt in range(attempts):
        status, body = _send(url, timeout)
        if 200 <= status < 300:
            return json.loads(body)
        # 4xx and other non-2xx responses are not retried; 5xx is retried until attempts run out.
        if status < 500 or attempt == attempts - 1:
            raise HTTPStatusError(status, url)
    raise AssertionError("unreachable")

